use inventory_server::Service;
use serde_json::{json,Value};
use uuid::Uuid;
fn save(s:&mut Service,action:&str,payload:Value)->Result<Value,String>{let state=s.state()?;s.mutate(&json!({"operation_id":Uuid::new_v4().to_string(),"epoch":state["epoch"],"expected_revision":state["revision"],"action":action,"payload":payload})).map(|v|v["result"].clone())}
fn entry(s:&mut Service,code:&str,qty:i64,cost:i64){save(s,"stock_entry",json!({"item_code":code,"name":"Battery بطارية","model_description":"Samsung S3","quantity":qty,"unit_cost_baisa":cost})).unwrap();}
fn snapshot(s:&mut Service)->Value{s.snapshot(json!({})).unwrap()["result"].clone()}
fn fixture()->(tempfile::TempDir,Service,String){let d=tempfile::tempdir().unwrap();let mut s=Service::open(d.path()).unwrap();entry(&mut s,"1",1,5000);save(&mut s,"stock_out",json!({"cr_number":"100","lines":[{"item_code":"1","quantity":1,"unit_price_baisa":25000}]})).unwrap();let id=snapshot(&mut s)["sale_lines"][0]["id"].as_str().unwrap().to_string();(d,s,id)}
fn warranty(id:&str,cr:&str)->Value{json!({"password":"1234","line_id":id,"quantity":1,"new_cr_number":cr,"replacement_item_code":"2","resolution":"replacement","refund_baisa":0,"extra_baisa":0,"note":"Factory issue"})}
#[test] fn example_links_both_crs_deducts_stock_and_cost_exactly_once(){let (_d,mut s,id)=fixture();entry(&mut s,"2",2,2000);save(&mut s,"warranty",warranty(&id,"200")).unwrap();let snap=snapshot(&mut s);let original=snap["sale_lines"].as_array().unwrap().iter().find(|l|l["id"]==id).unwrap();assert_eq!(original["profit_baisa"],20000);assert_eq!(original["adjusted_profit_baisa"],18000);assert_eq!(original["warranty_cost_baisa"],2000);let replacement=snap["sale_lines"].as_array().unwrap().iter().find(|l|l["purpose"]=="replacement").unwrap();assert_eq!(replacement["cr_number"],"200");assert_eq!(replacement["warranty"]["original_cr"],"100");assert_eq!(replacement["revenue_baisa"],0);assert_eq!(snap["summary"]["monthly_sales_baisa"],25000);assert_eq!(snap["summary"]["monthly_units_sold"],1);assert_eq!(snap["summary"]["monthly_profit_baisa"],18000);assert_eq!(snap["summary"]["total_units"],1);assert!(save(&mut s,"warranty",warranty(&id,"201")).is_err());}
#[test] fn rejects_same_cr_password_payment_and_insufficient_stock(){let (_d,mut s,id)=fixture();let state=s.state().unwrap();assert!(save(&mut s,"warranty",warranty(&id,"200")).is_err());assert_eq!(state,s.state().unwrap());entry(&mut s,"2",1,2000);let mut p=warranty(&id,"100");assert!(save(&mut s,"warranty",p.clone()).is_err());p["new_cr_number"]=json!("200");p["password"]=json!("wrong");assert!(save(&mut s,"warranty",p.clone()).is_err());p["password"]=json!("1234");p["extra_baisa"]=json!(1);assert!(save(&mut s,"warranty",p).is_err());}
#[test] fn replacement_failure_attributes_cost_to_original_sale(){let (_d,mut s,id)=fixture();entry(&mut s,"2",3,2000);save(&mut s,"warranty",warranty(&id,"200")).unwrap();let replacement=snapshot(&mut s)["sale_lines"].as_array().unwrap().iter().find(|l|l["purpose"]=="replacement").unwrap()["id"].as_str().unwrap().to_string();save(&mut s,"warranty",warranty(&replacement,"300")).unwrap();let snap=snapshot(&mut s);let original=snap["sale_lines"].as_array().unwrap().iter().find(|l|l["id"]==id).unwrap();assert_eq!(original["adjusted_profit_baisa"],16000);assert_eq!(original["warranties"].as_array().unwrap().len(),2);assert_eq!(snap["summary"]["monthly_profit_baisa"],16000);assert_eq!(snap["summary"]["monthly_units_sold"],1);}
#[test] fn backup_restore_preserves_links_and_financials(){let (_d,mut s,id)=fixture();entry(&mut s,"2",1,2000);save(&mut s,"warranty",warranty(&id,"200")).unwrap();let original=snapshot(&mut s);let bytes=s.backup().unwrap();let state=s.state().unwrap();s.restore(&bytes,&state).unwrap();let restored=snapshot(&mut s);assert_eq!(original["summary"],restored["summary"]);assert_eq!(original["sale_lines"],restored["sale_lines"]);}
